public class PerfectNumber {
    public static void main(String[] args) {
        int num = 28;
        int divisorSum = 0;
        for (int i = 1; i <= num / 2; i++) {  // Proper divisors up to num/2
            if (num % i == 0) {
                divisorSum += i;
            }
        }
        if (divisorSum == num) {
            System.out.println(num + " is a perfect number."); // Yes
        } else {
            System.out.println(num + " is not a perfect number.");
        }
    }
}
// Perfect numbers up to 1000: 6, 28, 496
// Key: iterate only up to num/2 — divisors larger than num/2 (other than num itself) don't exist

