for (int i = 5; i >= 1; i--) {
    for (int j = 1; j <= i; j++) {
        System.out.print(j + " ");
    }
    System.out.println();
}
// Outer loop i goes from 5 down to 1 (controls how many numbers per row)
// Inner loop j goes from 1 to i (prints numbers 1 through i)
// Row 1: i=5 → j: 1 2 3 4 5
// Row 2: i=4 → j: 1 2 3 4
// ... etc.
// Key: outer loop decrements (i--), inner loop always starts from 1

