for (int num = 1; num <= 1000; num++) {
    String s = String.valueOf(num);
    int digits = s.length();
    int sum = 0;
    for (int i = 0; i < digits; i++) {
        int digit = s.charAt(i) - '0';
        int power = 1;
        for (int p = 0; p < digits; p++) power *= digit; // digit^digits
        sum += power;
    }
    if (sum == num) System.out.print(num + " ");
}
System.out.println();
// Output: 1 2 3 4 5 6 7 8 9 153 370 371 407
// Alternative: use Math.pow(digit, digits) — simpler but uses double

